/* Market-data credentials are independent from the AI provider and stay server-side. */
const originalMarketSettings=wsSettings,originalMarketSettingsBind=bind;
let marketSettingsBusy=false;
wsSettings=function(){return originalMarketSettings()+`<section class="ws-card" style="margin-top:24px"><div class="ws-card-head"><h2>股市行情來源</h2><button class="textbtn" data-page="markets">查看股市資訊 ↗</button></div><p class="ws-caption">台股以證交所公開收盤資料為主；美股、ETF與指數使用 Twelve Data。資料權限與延遲依供應商方案，DeepSeek Key 不能用於行情。行情不會自動修改你的手動持倉。</p><form id="marketConfigForm"><div class="field"><label for="marketApiKey">Twelve Data 行情 API Key</label><input id="marketApiKey" type="password" autocomplete="off" maxlength="512" placeholder="僅送往本機後端，留空儲存會清除" ${demoMode?'disabled':''}></div><p class="ws-caption">${demoMode?'體驗頁不接收金鑰；正式後端啟動後才能設定真實行情。':'金鑰只留在後端執行期間；也可設定 LEDGER_TWELVE_DATA_API_KEY 環境變數。'}</p><div class="actions" style="justify-content:start">${btn('儲存行情設定','type="submit" '+(demoMode?'disabled':''),'primary')}${btn('檢查行情設定','type="button" id="marketCheckSettings"')}</div><p id="marketConfigStatus" role="status" aria-live="polite" class="ws-caption"></p></form></section>`};
bind=function(){originalMarketSettingsBind();el('#marketConfigForm')?.addEventListener('submit',async e=>{e.preventDefault();if(demoMode||marketSettingsBusy)return;marketSettingsBusy=true;const input=el('#marketApiKey'),key=input.value;input.value='';try{const result=await api('/api/markets/configure',{key});el('#marketConfigStatus').textContent=result.configured?'行情Key已保存在服務記憶體；請到股市資訊更新，確認權限與實際資料。':'已清除行情Key。'}catch(error){el('#marketConfigStatus').textContent='設定未完成：'+error.message}finally{marketSettingsBusy=false}});el('#marketCheckSettings')?.addEventListener('click',async()=>{const status=el('#marketConfigStatus');if(demoMode){status.textContent='體驗頁只使用合成行情，沒有設定或呼叫真實行情服務。';return}try{const result=await api('/api/markets/status');status.textContent=result.configured?'已設定獨立行情Key；未代表行情權限或連線已驗證。':'未設定美股行情Key；台股仍可嘗試公開收盤來源。'}catch(error){status.textContent='無法查詢行情設定：'+error.message}})};
